CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261120131013_PostgreSqlInitial') THEN
    CREATE TABLE "Equipment" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Name" text NOT NULL,
        "Identifier" text NOT NULL,
        "Description" text,
        "IsAvailable" boolean NOT NULL,
        "NormalizedIdentifier" text GENERATED ALWAYS AS (upper(btrim("Identifier"))) STORED,
        CONSTRAINT "PK_Equipment" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_Equipment_Description" CHECK ("Description" IS NULL OR length(btrim("Description")) > 0),
        CONSTRAINT "CK_Equipment_Required" CHECK (length(btrim("Name")) > 0 AND length(btrim("Identifier")) > 0)
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261120131013_PostgreSqlInitial') THEN
    CREATE TABLE "Students" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Name" text NOT NULL,
        "StudentNumber" text NOT NULL,
        "Contact" text,
        "IsAllowedToBorrow" boolean NOT NULL,
        "NormalizedNumber" text GENERATED ALWAYS AS (upper(btrim("StudentNumber"))) STORED,
        CONSTRAINT "PK_Students" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_Student_Contact" CHECK ("Contact" IS NULL OR length(btrim("Contact")) > 0),
        CONSTRAINT "CK_Student_Required" CHECK (length(btrim("Name")) > 0 AND length(btrim("StudentNumber")) > 0)
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261120131013_PostgreSqlInitial') THEN
    CREATE TABLE "Borrowings" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "StudentId" integer NOT NULL,
        "EquipmentId" integer NOT NULL,
        "BorrowedDate" date NOT NULL,
        "ExpectedReturnDate" date NOT NULL,
        "Status" integer NOT NULL,
        "ActualReturnDate" date,
        CONSTRAINT "PK_Borrowings" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_Borrowing_Due" CHECK ("ExpectedReturnDate" > "BorrowedDate"),
        CONSTRAINT "CK_Borrowing_Return" CHECK (("Status" = 0 AND "ActualReturnDate" IS NULL) OR ("Status" = 1 AND "ActualReturnDate" IS NOT NULL AND "ActualReturnDate" >= "BorrowedDate")),
        CONSTRAINT "FK_Borrowings_Equipment_EquipmentId" FOREIGN KEY ("EquipmentId") REFERENCES "Equipment" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_Borrowings_Students_StudentId" FOREIGN KEY ("StudentId") REFERENCES "Students" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261120131013_PostgreSqlInitial') THEN
    CREATE UNIQUE INDEX "IX_Borrowings_EquipmentId" ON "Borrowings" ("EquipmentId") WHERE "Status" = 0;
    END IF;
END $EF$;

DO $EF$
